import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';

@Component({
  selector: 'app-all-companies',
  templateUrl: './all-companies.component.html',
  styleUrls: ['./all-companies.component.css']
})
export class AllCompaniesComponent {

    constructor(private router:Router , private jobService:JobService ,private compService:CompanyService){}


  signup(){
    this.router.navigate(['/register'])
  }

  login(){
    this.router.navigate(['/login']);
  }
    ngOnInit(){
      this.getAllJobs();
      this.getAllCompanies();
    }

  jobs:Job[] = [];
  companies:Company[] = [];

    getAllJobs() {
    this.jobService.getAllJobs().subscribe((res) => {
      this.jobs = res
    });
  }

    getAllCompanies(){
      this.compService.getAllCompanies().subscribe(
        (res)=>
          this.companies = res
      )
    }


}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Browse Companies · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

</head>
<body>
<div class="page">
<header class="topnav">
  <div class="wrap">
    <a href="index.html" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links">
      <a href="jobs.html">Find Jobs</a>
      <a href="companies.html" class="active">Companies</a>
      <a href="register-company.html">For Employers</a>
    </nav>
    <div class="nav-actions">
      <a (click)="login()" class="btn btn-ghost-dark btn-sm">Log in</a>
      <a (click)="signup()" class="btn btn-primary btn-sm">Sign up</a>
    </div>
  </div>
</header>

<section class="section-pad">
  <div class="wrap">
    <div class="section-head">
      <h2>{{companies.length}} companies hiring</h2>
      <input type="text" placeholder="Search companies" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;width:240px;">
    </div>
    <div class="table-wrap">
      <table>
  <thead>
    <tr>
      <th>Company</th>
      <th>Location</th>
      <th>Open Roles</th>
      <th>Website</th>
      <th></th>
    </tr>
  </thead>

  <tbody>
    <tr *ngFor="let comp of companies">
      <td>{{ comp.companyName }}</td>
      <td>{{ comp.location }}</td>
      <td>{{ comp.jobs?.length || 0 }}</td>
      <td>{{ comp.website }}</td>
      <td class="actions">
        <a href="#">View</a>
      </td>
    </tr>
  </tbody>
</table>
    </div>
  </div>
</section>

<footer class="site-footer">
  <div class="wrap">
    <span>© 2026 HireHub</span>
    <span class="mono-label" style="color:var(--muted-lt)">com.aitrich.JobPortalSystem</span>
  </div>
</footer>
</div>
</body>
</html>
